fn main(){let root="research/hec_tensorprod631_20261116/timing";let mut v:BTreeMap<String,Vec<u128>>=BTreeMap::new();let mut p:BTreeMap<(String,String),Vec<u128>>=BTreeMap::new();let s=fs::read_to_string(format!("{root}/cells.tsv")).unwrap();for l in s.lines().skip(1){let a:Vec<_>=l.split('\t').collect();assert_eq!(a[2],"0");v.entry(a[1].into()).or_default().push(a[4].parse().unwrap());if a[1].ends_with("_a"){for(path,prefix)in[(format!("{root}/{}-{}/work/reconstruct.stdout",a[0],a[1]),"TRACE_"),(format!("{root}/{}-{}.stdout",a[0],a[1]),"STAGE_WALL")]{for l in fs::read_to_string(path).unwrap().lines().filter(|l|if prefix=="TRACE_"{l.starts_with("TRACE_PHASE ")||l.starts_with("TRACE_AGGREGATE ")}else{l.starts_with(prefix)}){let f:BTreeMap<_,_>=l.split_whitespace().skip(1).filter_map(|s|s.split_once('=')).collect();let key=f.get("name").or(f.get("label")).unwrap();if key.starts_with("candidate_"){continue}p.entry((a[1].into(),key.to_string())).or_default().push(f["wall_ns"].parse().unwrap());}}}}assert_eq!(v.len(),4);let mut stable=true;for(a,x)in &mut v{x.sort();assert_eq!(x.len(),5);let good=x[4]*100<=x[0]*125;stable&=good;println!("ARM {a} median_ns={} min_ns={} max_ns={} spread_ratio={:.12} spread_pass={good}",x[2],x[0],x[4],x[4]as f64/x[0]as f64);}for a in["baseline","tensor"]{let x=med(&v[&format!("{a}_a")]);let y=med(&v[&format!("{a}_b")]);let good=x.max(y)*100<=x.min(y)*110;stable&=good;println!("AA {a} ratio={:.12} pass={good}",x.max(y)as f64/x.min(y)as f64);}let b=med(&v["baseline_a"]);let t=med(&v["tensor_a"]);let ratio=b as f64/t as f64;println!("GATE correctness=true stability={stable} numerical_10x={} ratio={ratio:.12} qualified_10x={}",b>=10*t,stable&&b>=10*t);for((a,n),x)in p{println!("PHASE arm={a} name={n} median_ns={} n={} inclusive_nested=true",med(&x),x.len());}let max=v.values().map(|x|med(x)).max().unwrap()as f64;let mut svg=String::from("<svg xmlns='http://www.w3.org/2000/svg' width='900' height='370'><rect width='900' height='370' fill='white'/><g font-family='sans-serif'><text x='25' y='30' font-size='22'>Compiled target maps: 20 class checks pass; stability fails</text>");for(i,a)in["baseline_a","baseline_b","tensor_a","tensor_b"].iter().enumerate(){let ns=med(&v[*a])as f64;let y=55+i*65;let w=ns/max*570.;svg+=&format!("<text x='25' y='{}'>{a}</text><rect x='130' y='{y}' width='{w}' height='35' fill='#397e91'/><text x='{}' y='{}'>{:.6} s</text>",y+24,w+140.,y+24,ns/1e9);}svg+=&format!("<text x='25' y='350'>Observed primary ratio {ratio:.3}x; unqualified by frozen stability gate; 10x fails</text></g></svg>");fs::write("research/hec_tensorprod631_20261116/COST.svg",svg).unwrap();}
